text:
  & .panel-subsection {
    display: flex;
    flex-direction: column;
    gap: calc(2 * var(--space-base));
  }
}

.form-selection {
  position: sticky;
  inset-block-start: 0;
  display: flex;
  flex-direction: column;
  gap: var(--hub-space-large);
  background-color: var(--color-surface-base);
  padding: var(--hub-space-medium);
  border: 1px solid var(--color-primary-default);
  border-radius: 10px;

  &.credentials-confirmation {
    inline-size: fit-content;
    min-inline-size: 380px;
    margin-inline: auto;
  }

  &.config-selection {
    gap: 0;
    &.single {
      gap: var(--hub-space-medium);
    }
